mapper.select:
SELECT o.id, o.order_no, o.warehouse_id, w.name AS warehouse_name, o.from_location_id, o.from_location_code, o.to_location_id, o.to_location_code, o.status, o.total_qty, o.remark, o.transfer_time, o.create_time, o.update_time FROM transfer_order o LEFT JOIN warehouse w ON w.id = o.warehouse_id AND w.deleted = 0 WHERE o.deleted = 0
AND (o.order_no LIKE CONCAT('%', #{query.keyword}, '%') OR o.from_location_code LIKE CONCAT('%', #{query.keyword}, '%') OR o.to_location_code LIKE CONCAT('%', #{query.keyword}, '%'))
AND o.warehouse_id = #{query.warehouseId}
AND o.from_location_id = #{query.fromLocationId}
AND o.to_location_id = #{query.toLocationId}
AND o.status = #{query.status}
AND o.create_time >= #{query.beginTime}
AND o.create_time < DATE_ADD(#{query.endTime}, INTERVAL 1 DAY)
ORDER BY FIELD(o.status, 'CREATED', 'COMPLETED', 'CANCELLED') ASC, o.id DESC

mapper.update:
UPDATE transfer_order
SET status    = 'CANCELLED',
    update_by = #{updateBy}
WHERE id = #{id}
  AND status = 'CREATED'
  AND deleted = 0
